INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d6c3dab7-7d22-4195-92f3-472f6de6bc16', '051b209e-9985-44da-a832-ca884783cb98', 2, 'O Ordenamento dos Afetos', NULL, '{"intro": "Desordem emocional gera ansiedade constante.", "prayer": "Ore pedindo a gra\u00e7a de amar o que \u00e9 eterno.", "practice": "Escolha um objeto em sua casa e o organize conscientemente.", "reflection": "Amar \u00e9 colocar as coisas no seu devido lugar.", "journal_prompt": "Seus amores est\u00e3o em ordem?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;